      .example {
        border: 1px solid var(--border);
        border-radius: 20px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.015));
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .question {
        width: 100%;
        padding: 22px 24px;
